175	    flowSteps,
176	    timelineStates,
177	  }), [detail?.project.id, detail?.project.name, entities, flowSteps, flows, graphOverride, relations, timelineStates, viewRevision]);
178	  const fingerprint = useMemo(() => semanticGraphFingerprint(graph), [graph]);
179	  const storageKey = useMemo(() => layoutStorageKey(graph), [graph]);
180	  const view = useMemo(() => deriveCanvasView(graph, interaction), [graph, interaction]);
181	  const inspectorBinding = useMemo(() => bindInspector(graph, interaction.selection), [graph, interaction.selection]);
182	  const projection = useMemo(() => layout ? projectSemanticGraph(graph, layout, view) : { nodes: [], edges: [] }, [graph, layout, view]);
183	  const searchResults = useMemo(() => interaction.searchQuery.trim()
184	    ? graph.objects.filter((object) => view.searchMatches.has(object.id)).slice(0, 8)
185	    : [], [graph.objects, interaction.searchQuery, view.searchMatches]);
186	
187	  const fitCanvas = useCallback((state: Pick<CanvasInteractionState, "mode" | "selection" | "activeFlowId">, duration = 360) => {
188	    const instance = instanceRef.current;
189	    if (!instance) return;
190	    const targetObjectIds = new Set<string>();
191	    if (state.mode === "trace" && state.activeFlowId) {
192	      const flow = graph.flows.find((candidate) => candidate.id === state.activeFlowId);
193	      for (const objectId of flow?.objectIds ?? []) targetObjectIds.add(objectId);
194	    } else if ((state.mode === "focus" || state.mode === "inspect") && state.selection?.kind === "object") {
195	      targetObjectIds.add(state.selection.id);
196	      for (const relationship of graph.relationships) {
197	        if (relationship.sourceObjectId === state.selection.id) targetObjectIds.add(relationship.targetObjectId);
198	        if (relationship.targetObjectId === state.selection.id) targetObjectIds.add(relationship.sourceObjectId);
199	      }
200	    } else if (state.mode === "inspect" && state.selection?.kind === "relationship") {
201	      const relationship = graph.relationships.find((candidate) => candidate.id === state.selection?.id);
202	      if (relationship) {
203	        targetObjectIds.add(relationship.sourceObjectId);
204	        targetObjectIds.add(relationship.targetObjectId);
205	      }
206	    }
207	    const allNodes = instance.getNodes();
208	    const targetNodes = targetObjectIds.size > 0
209	      ? allNodes.filter((node) => targetObjectIds.has(node.id))
210	      : allNodes;
211	    if (targetNodes.length === 0) return;
212	    void instance.fitView({
213	      ...canvasFitOptions(state.mode, duration),
214	      nodes: targetNodes,
215	    });
216	  }, [graph.flows, graph.relationships]);
217	
218	  useEffect(() => {
219	    if (!playingTimeline) return;
220	    const timer = window.setInterval(() => {
221	      setRevisionIndex((index) => {
222	        if (index >= revisionOptions.length - 1) {
223	          setPlayingTimeline(false);
224	          return index;
225	        }
226	        return index + 1;
227	      });
228	    }, 1300);
229	    return () => window.clearInterval(timer);
230	  }, [playingTimeline, revisionOptions.length]);
231	
232	  useEffect(() => {
233	    let cancelled = false;
234	    const cacheKey = `${storageKey}:${fingerprint}`;
235	    const cached = layoutReset === 0 ? layoutMemory.get(cacheKey) ?? readLayout(storageKey, fingerprint) : null;
236	    if (cached) {
237	      previousLayoutRef.current = cached;
238	      const timer = window.setTimeout(() => {
239	        setLayout(cached);
240	        setLayouting(false);
241	        setLayoutError("");
242	      }, 0);
243	      return () => window.clearTimeout(timer);
244	    }
245	    const loadingTimer = window.setTimeout(() => setLayouting(true), 0);
246	    void layoutSemanticGraph(graph, { previousLayout: previousLayoutRef.current ?? undefined })
247	      .then((nextLayout) => {
248	        if (cancelled) return;
249	        previousLayoutRef.current = nextLayout;
250	        writeLayout(storageKey, nextLayout);
251	        setLayout(nextLayout);
252	        setLayoutError("");
253	        setLayouting(false);
254	      })
255	      .catch(() => {
256	        if (cancelled) return;
257	        setLayout(previousLayoutRef.current);
258	        setLayoutError("ELK could not arrange this graph. The last stable local layout is preserved.");
259	        setLayouting(false);
260	      });
261	    return () => { cancelled = true; window.clearTimeout(loadingTimer); };
262	  }, [fingerprint, graph, layoutReset, storageKey]);
263	
264	  useEffect(() => {
265	    setNodes(projection.nodes);
266	    setEdges(projection.edges);
267	    const layoutIdentity = layout ? `${storageKey}:${layout.fingerprint}` : "";
268	    if (layoutIdentity && fittedLayoutRef.current !== layoutIdentity) {
269	      fittedLayoutRef.current = layoutIdentity;
270	      const timer = window.setTimeout(() => fitCanvas(interaction, 420), 70);
271	      return () => window.clearTimeout(timer);
272	    }
273	    return undefined;
274	  }, [fitCanvas, interaction, layout, projection, setEdges, setNodes, storageKey]);
275	
276	  useEffect(() => {
277	    if (!layout) return undefined;
278	    const selectionKey = interaction.selection ? `${interaction.selection.kind}:${interaction.selection.id}` : "none";
279	    const cameraIntent = `${layout.fingerprint}:${interaction.mode}:${interaction.activeFlowId ?? "none"}:${selectionKey}:${inspectorBinding ? "docked" : "open"}`;
280	    if (cameraIntentRef.current === cameraIntent) return undefined;
281	    cameraIntentRef.current = cameraIntent;
282	    const timer = window.setTimeout(() => fitCanvas(interaction, 360), 70);
283	    return () => window.clearTimeout(timer);
284	  }, [fitCanvas, inspectorBinding, interaction, layout]);
285	
286	  useEffect(() => {
287	    const availableObjects = new Set(graph.objects.map((object) => object.id));
288	    const availableRelationships = new Set(graph.relationships.map((relationship) => relationship.id));
289	    const availableFlows = new Set(graph.flows.map((flow) => flow.id));
290	    const selection = interaction.selection;
291	    const valid = !selection
292	      || (selection.kind === "object" && availableObjects.has(selection.id))
293	      || (selection.kind === "relationship" && availableRelationships.has(selection.id))
294	      || (selection.kind === "flow" && availableFlows.has(selection.id));
295	    if (!valid || (interaction.activeFlowId && !availableFlows.has(interaction.activeFlowId))) {
296	      const timer = window.setTimeout(() => setInteraction((current) => ({ ...current, mode: "browse", selection: null, activeFlowId: null })), 0);
297	      return () => window.clearTimeout(timer);
298	    }
299	    return undefined;
300	  }, [graph, interaction.activeFlowId, interaction.selection]);
301	
302	  const select = useCallback((selection: CanvasSelection) => {
303	    setInteraction((current) => {
304	      if (!selection) return { ...current, mode: "browse", selection: null, activeFlowId: null };
305	      if (selection.kind === "flow") return { ...current, mode: "trace", selection, activeFlowId: selection.id };
306	      if (current.mode === "trace") return { ...current, selection };
307	      if (current.mode === "focus" && selection.kind === "object") return { ...current, selection, activeFlowId: null };
308	      return { ...current, mode: "inspect", selection, activeFlowId: null };
309	    });
310	  }, []);
311	
312	  const focusObject = useCallback((objectId: string) => {
313	    setInteraction((current) => ({ ...current, mode: "focus", selection: { kind: "object", id: objectId }, activeFlowId: null }));
314	  }, []);
315	
316	  useEffect(() => {
317	    const onKeyDown = (event: KeyboardEvent) => {
318	      const target = event.target as HTMLElement | null;
319	      if (target?.matches("input, textarea, select, [contenteditable='true']")) return;
320	      if (event.key.toLowerCase() === "f" && interaction.selection?.kind === "object") focusObject(interaction.selection.id);
321	      if (event.key === "Escape") select(null);
322	    };
323	    window.addEventListener("keydown", onKeyDown);
324	    return () => window.removeEventListener("keydown", onKeyDown);
325	  }, [focusObject, interaction.selection, select]);
326	
327	  function handleNodeDragStop(node: CanvasObjectNode) {
328	    if (!layout) return;
329	    const previousRect = layout.objectRects[node.id];
330	    if (!previousRect) return;
331	    const incidentRelationshipIds = new Set(graph.relationships
332	      .filter((relationship) => relationship.sourceObjectId === node.id || relationship.targetObjectId === node.id)
333	      .map((relationship) => relationship.id));
334	    const nextLayout: CanvasLayout = {
335	      ...layout,
336	      objectRects: { ...layout.objectRects, [node.id]: { ...previousRect, x: node.position.x, y: node.position.y } },
337	      relationshipRoutes: Object.fromEntries(Object.entries(layout.relationshipRoutes).filter(([id]) => !incidentRelationshipIds.has(id))),
338	    };
339	    previousLayoutRef.current = nextLayout;
340	    writeLayout(storageKey, nextLayout);
341	    setLayout(nextLayout);
342	  }
343	
344	  function resetLayout() {
345	    try { window.localStorage.removeItem(storageKey); } catch { /* no-op */ }
346	    layoutMemory.delete(`${storageKey}:${fingerprint}`);
347	    previousLayoutRef.current = null;
348	    fittedLayoutRef.current = "";
349	    cameraIntentRef.current = "";
350	    setLayoutReset((value) => value + 1);
351	  }
352	
353	  function handlePaneClick() {
354	    if (interaction.mode === "trace") setInteraction((current) => ({ ...current, selection: null }));
355	    else select(null);
356	  }
357	
358	  async function toggleFullscreen() {
359	    if (!document.fullscreenElement) await canvasRef.current?.requestFullscreen();
360	    else await document.exitFullscreen();
361	  }
362	
363	  if (!graphOverride && isCurrentRevision && baseEntities.length === 0 && !showPending) {
364	    return (
365	      <section className="architecture-empty-state">
366	        <small>Architecture Model 尚未建立</small>
367	        <h2>这个 Project 还没有可发布的架构对象</h2>
368	        <p>Human Web 不负责画图。维护 Agent 应通过 revision-pinned Change 提交 Architecture Observation、Evidence 和关系模型。</p>
369	        {pendingEntities.length > 0 && <button onClick={() => setShowPending(true)} type="button">预览 {pendingEntities.length} 个待发布对象</button>}
370	        {detail && <Link href={`/maintenance?project=${encodeURIComponent(detail.project.id)}&tab=facts`}>查看 Project Registry</Link>}
371	      </section>
372	    );
373	  }
374	
375	  return (
376	    <div className="architecture-workbench" ref={canvasRef}>
377	      <header className="canvas-commandbar">
378	        <nav className="canvas-modes" aria-label="Canvas mode">
379	          <button className={interaction.mode === "browse" ? "active" : ""} onClick={() => select(null)} type="button">Browse</button>
380	          <button className={interaction.mode === "inspect" ? "active" : ""} disabled={!interaction.selection || interaction.selection.kind === "flow"} onClick={() => setInteraction((current) => ({ ...current, mode: "inspect", activeFlowId: null }))} type="button">Inspect</button>
381	          <button className={interaction.mode === "focus" ? "active" : ""} disabled={interaction.selection?.kind !== "object"} onClick={() => interaction.selection?.kind === "object" && focusObject(interaction.selection.id)} type="button">Focus</button>
382	          <button className={interaction.mode === "trace" ? "active" : ""} onClick={() => setFlowLensOpen((open) => !open)} type="button">Trace <b>{graph.flows.length}</b></button>
383	        </nav>
384	        <div className="canvas-search">
385	          <input aria-label="Search architecture objects" onChange={(event) => setInteraction((current) => ({ ...current, searchQuery: event.target.value }))} placeholder="Search objects…" value={interaction.searchQuery} />
386	          {searchResults.length > 0 && (
387	            <div className="canvas-search-results">
388	              {searchResults.map((object) => <button key={object.id} onClick={() => { select({ kind: "object", id: object.id }); setInteraction((current) => ({ ...current, searchQuery: "" })); }} type="button"><span>{object.objectType}</span><strong>{object.name}</strong></button>)}
389	            </div>
390	          )}
391	        </div>
392	        <div className="canvas-command-actions">
393	          {detail && isCurrentRevision && pendingEntities.length > 0 && <button className={showPending ? "active" : ""} onClick={() => setShowPending((value) => !value)} type="button">Change Overlay <b>{pendingEntities.length}</b></button>}
394	          <button onClick={() => fitCanvas(interaction, 300)} type="button">Fit</button>
395	          <button onClick={resetLayout} type="button">Layout</button>
396	          <button onClick={() => void toggleFullscreen()} type="button">Full</button>
397	        </div>
398	      </header>
399	
400	      {detail && revisionOptions.length > 1 && (
401	        <div className="revision-timeline">
402	          <button aria-label={playingTimeline ? "暂停 Revision Timeline" : "播放 Revision Timeline"} onClick={() => {
403	            if (revisionIndex >= revisionOptions.length - 1) setRevisionIndex(0);
404	            setPlayingTimeline((playing) => !playing);
405	            select(null);
406	          }} type="button">{playingTimeline ? "Pause" : "Play"}</button>
407	          <small>Architecture Timeline</small>
408	          <input aria-label="选择 Project Revision" max={revisionOptions.length - 1} min="0" onChange={(event) => { setPlayingTimeline(false); setShowPending(false); select(null); setRevisionIndex(Number(event.target.value)); }} step="1" type="range" value={revisionIndex} />
409	          <strong>r{viewRevision}</strong>
410	          <span>{isCurrentRevision ? "Current" : "Snapshot"}</span>
411	        </div>
412	      )}
413	
414	      <div className={`canvas-stage ${inspectorBinding ? "has-inspector" : ""}`}>
415	        <div className="canvas-viewport">
416	          <ArchitectureCanvasKernel
417	            edges={edges}
418	            mode={interaction.mode}
419	            nodes={nodes}
420	            onEdgeClick={(edge) => select({ kind: "relationship", id: edge.id })}
421	            onEdgesChange={onEdgesChange}
422	            onInit={(instance) => { instanceRef.current = instance; }}
423	            onNodeClick={(node) => select({ kind: "object", id: node.id })}
424	            onNodeDragStop={handleNodeDragStop}
425	            onNodesChange={onNodesChange}
426	            onPaneClick={handlePaneClick}
427	            onViewportChange={(viewport) => setInteraction((current) => Math.abs(current.zoom - viewport.zoom) < 0.015 ? current : { ...current, zoom: viewport.zoom })}
428	          >
429	            <div className="canvas-reading-key">
430	              <span><i className="object-key" /> Object</span>
431	              <span><i className="relationship-key" /> Relationship</span>
432	              {interaction.mode === "trace" && <span><i className="trace-key" /> Active Flow</span>}
433	              <em>{interaction.mode === "trace" ? "动画表示语义顺序，不代表实时流量" : "拖动只调整本机视图，不改变架构关系"}</em>
434	            </div>
435	          </ArchitectureCanvasKernel>
436	
437	          {flowLensOpen && <FlowPanel activeFlowId={interaction.activeFlowId} flows={graph.flows} onClose={() => setFlowLensOpen(false)} onSelect={(flowId) => { select({ kind: "flow", id: flowId }); setFlowLensOpen(false); }} />}
438	          {layouting && <div className="canvas-layouting">ELK is arranging the system…</div>}
439	          {layoutError && <div className="canvas-layout-error" role="status">{layoutError}</div>}
440	        </div>
441	        <Inspector binding={inspectorBinding} mode={interaction.mode} onClose={() => interaction.mode === "trace" ? setInteraction((current) => ({ ...current, selection: null })) : select(null)} onFocus={focusObject} onSelect={select} />
442	      </div>
443	
444	      <footer className="canvas-statusbar">
445	        <span>{interaction.mode.toUpperCase()} · {view.zoomLevel}</span>
446	        <span>{graph.regions.length} Regions · {graph.objects.length} Objects · {graph.relationships.length} Relationships · {graph.flows.length} Flows</span>
447	        <span>{layout ? `ELK ${layout.durationMs} ms` : "Layout pending"} · r{graph.scope.revision}</span>
448	        <span>Human Read Model · 只读</span>
449	      </footer>
450	    </div>
451	  );
452	}
