1	import {
2	  indexSemanticGraph,
3	  type SemanticFlow,
4	  type SemanticGraph,
5	  type SemanticObject,
6	  type SemanticRegion,
7	  type SemanticRelationship,
8	  type SemanticState,
9	} from "./semantic-graph";
10	import type { CanvasSelection } from "./interaction";
11	
12	type InspectorBase = {
13	  id: string;
14	  title: string;
15	  typeLabel: string;
16	  summary: string;
17	  state: SemanticState;
18	  location: string;
19	  raw: Record<string, unknown>;
20	};
21	
22	export type ObjectInspectorBinding = InspectorBase & {
23	  kind: "object";
24	  object: SemanticObject;
25	  region?: SemanticRegion;
26	  incoming: SemanticRelationship[];
27	  outgoing: SemanticRelationship[];
28	  flows: SemanticFlow[];
29	};
30	
31	export type RelationshipInspectorBinding = InspectorBase & {
32	  kind: "relationship";
33	  relationship: SemanticRelationship;
34	  source?: SemanticObject;
35	  target?: SemanticObject;
36	  flows: SemanticFlow[];
37	};
38	
39	export type FlowInspectorBinding = InspectorBase & {
40	  kind: "flow";
41	  flow: SemanticFlow;
42	  objects: SemanticObject[];
43	  relationships: SemanticRelationship[];
44	};
45	
46	export type InspectorBinding = ObjectInspectorBinding | RelationshipInspectorBinding | FlowInspectorBinding;
47	
48	export function bindInspector(graph: SemanticGraph, selection: CanvasSelection): InspectorBinding | null {
49	  if (!selection) return null;
50	  const index = indexSemanticGraph(graph);
51	  if (selection.kind === "object") {
52	    const object = index.objectById.get(selection.id);
53	    if (!object) return null;
54	    const region = index.regionById.get(object.regionId);
55	    const incoming = index.incomingByObjectId.get(object.id) ?? [];
56	    const outgoing = index.outgoingByObjectId.get(object.id) ?? [];
57	    const flows = graph.flows.filter((flow) => flow.objectIds.includes(object.id));
58	    return {
59	      kind: "object",
60	      id: object.id,
61	      title: object.name,
62	      typeLabel: object.objectType,
63	      summary: object.summary || "尚无概述。",
64	      state: object.state,
65	      location: region?.name ?? "Unscoped",
66	      raw: { ...object.metadata, importance: object.importance, layoutHints: object.layoutHints },
67	      object,
68	      region,
69	      incoming,
70	      outgoing,
71	      flows,
72	    };
73	  }
74	  if (selection.kind === "relationship") {
75	    const relationship = index.relationshipById.get(selection.id);
76	    if (!relationship) return null;
77	    const source = index.objectById.get(relationship.sourceObjectId);
78	    const target = index.objectById.get(relationship.targetObjectId);
79	    const flows = graph.flows.filter((flow) => flow.relationshipIds.includes(relationship.id));
80	    return {
81	      kind: "relationship",
82	      id: relationship.id,
83	      title: relationship.label || relationship.relationshipType,
84	      typeLabel: `${relationship.relationshipType} relationship`,
85	      summary: relationship.summary || `${source?.name ?? relationship.sourceObjectId} → ${target?.name ?? relationship.targetObjectId}`,
86	      state: relationship.state,
87	      location: `${source?.name ?? relationship.sourceObjectId} → ${target?.name ?? relationship.targetObjectId}`,
88	      raw: { ...relationship.metadata, direction: relationship.direction, importance: relationship.importance, layoutHints: relationship.layoutHints },
89	      relationship,
90	      source,
91	      target,
92	      flows,
93	    };
94	  }
95	  const flow = index.flowById.get(selection.id);
96	  if (!flow) return null;
97	  const objects = flow.objectIds.map((id) => index.objectById.get(id)).filter((object): object is SemanticObject => Boolean(object));
98	  const relationships = flow.relationshipIds.map((id) => index.relationshipById.get(id)).filter((relationship): relationship is SemanticRelationship => Boolean(relationship));
99	  const regionCount = new Set(objects.map((object) => object.regionId)).size;
100	  return {
101	    kind: "flow",
102	    id: flow.id,
103	    title: flow.name,
104	    typeLabel: "Flow",
