"use client";

import {
  Background,
  BackgroundVariant,
  Controls,
  MiniMap,
  ReactFlow,
  type EdgeChange,
  type Node,
  type NodeChange,
  type ReactFlowInstance,
  type Viewport,
} from "@xyflow/react";
import { SmartEdgeProvider } from "@tisoap/react-flow-smart-edge";
import type { ReactNode } from "react";
import RelationshipEdge from "./architecture-edge";
import ObjectNode from "./architecture-node";
import RegionNode from "./region-node";
import type { CanvasMode } from "./interaction";
import type { CanvasNode, CanvasObjectNode, CanvasRelationshipEdge } from "./projection";
import type { ObjectNodeData } from "./types";

const nodeTypes = { object: ObjectNode, region: RegionNode };
const edgeTypes = { relationship: RelationshipEdge };

type CanvasKernelProps = {
  nodes: CanvasNode[];
  edges: CanvasRelationshipEdge[];
  mode: CanvasMode;
  onNodesChange: (changes: NodeChange<CanvasNode>[]) => void;
  onEdgesChange: (changes: EdgeChange<CanvasRelationshipEdge>[]) => void;
  onInit: (instance: ReactFlowInstance<CanvasNode, CanvasRelationshipEdge>) => void;
  onNodeClick: (node: CanvasObjectNode) => void;
  onEdgeClick: (edge: CanvasRelationshipEdge) => void;
  onNodeDragStop: (node: CanvasObjectNode) => void;
  onPaneClick: () => void;
  onViewportChange: (viewport: Viewport) => void;
  children?: ReactNode;
};

export default function ArchitectureCanvasKernel({
  nodes,
  edges,
  mode,
  onNodesChange,
  onEdgesChange,
  onInit,
  onNodeClick,
  onEdgeClick,
  onNodeDragStop,
  onPaneClick,
  onViewportChange,
  children,
}: CanvasKernelProps) {
  return (
    <SmartEdgeProvider
      nodes={nodes as Node[]}
      options={{
        preset: "smoothstep",
        routeOnlyWhenBlocked: false,
        routeWhileDragging: true,
        nodePadding: 18,
        gridRatio: 10,
        debounceMs: 16,
      }}
    >
      <ReactFlow<CanvasNode, CanvasRelationshipEdge>
        className={`architecture-canvas-kernel mode-${mode}`}
        edges={edges}
        edgesReconnectable={false}
        edgeTypes={edgeTypes}
        elementsSelectable
        elevateEdgesOnSelect
        maxZoom={1.85}
        minZoom={0.16}
        nodeTypes={nodeTypes}
        nodes={nodes}
        nodesConnectable={false}
        nodesDraggable
        onEdgeClick={(_, edge) => onEdgeClick(edge)}
        onEdgesChange={onEdgesChange}
        onInit={onInit}
        onMoveEnd={(_, viewport) => onViewportChange(viewport)}
        onNodeClick={(_, node) => { if (node.type === "object") onNodeClick(node as CanvasObjectNode); }}
        onNodeDragStop={(_, node) => { if (node.type === "object") onNodeDragStop(node as CanvasObjectNode); }}
        onNodesChange={onNodesChange}
        onPaneClick={onPaneClick}
        onlyRenderVisibleElements
        panOnDrag
        proOptions={{ hideAttribution: true }}
        selectionOnDrag={false}
        zoomOnDoubleClick={false}
      >
        <Background color="rgba(132,151,157,.24)" gap={28} size={1} variant={BackgroundVariant.Dots} />
        <Controls className="architecture-controls" showInteractive={false} />
        <MiniMap
          className="architecture-minimap"
          maskColor="rgba(9,14,17,.68)"
          nodeColor={(node) => node.type === "region" ? "rgba(118,139,145,.2)" : (node.data as ObjectNodeData | undefined)?.object.state.severity === "critical" ? "#bd7068" : "#688f89"}
          pannable
          zoomable
        />
        {children}
      </ReactFlow>
    </SmartEdgeProvider>
  );
}

