import type { ObjectEmphasis, RegionEmphasis, RelationshipEmphasis, SemanticZoomLevel } from "./interaction";
import type { RelationshipRoute } from "./layout";
import type { SemanticObject, SemanticRegion, SemanticRelationship } from "./semantic-graph";

export type CatalogProject = {
  id: string;
  name: string;
  description: string;
  repositoryRef: string;
  defaultBranch: string;
  projectCategory: string;
  registryVisibility: string;
  revision: number;
  healthScore: number;
  alignmentScore: number;
  maintenanceMode: string;
  activeChanges: number;
  facts: number;
  unknowns: number;
  activeAgents: number;
  passedEvidence: number;
  architectureEntities: number;
  architectureFlows: number;
  updatedAt: string;
};

export type ArchitectureEntity = {
  id: string;
  projectId: string;
  changeId: string;
  entityKey: string;
  entityType: string;
  name: string;
  summary: string;
  parentEntityKey: string | null;
  technology: string;
  repositoryRefsJson: string;
  knowledgeState: string;
  lifecycleStatus: string;
  validFromRevision: number;
  validToRevision: number | null;
  sourceObservationId: string;
};

export type ArchitectureRelation = {
  id: string;
  projectId: string;
  changeId: string;
  relationKey: string;
  sourceEntityKey: string;
  targetEntityKey: string;
  relationType: string;
  label: string;
  summary: string;
  knowledgeState: string;
  evidenceRefsJson: string;
  lifecycleStatus: string;
  validFromRevision: number;
  validToRevision: number | null;
  sourceObservationId: string;
};

export type ArchitectureFlow = {
  id: string;
  projectId: string;
  changeId: string;
  flowKey: string;
  name: string;
  summary: string;
  trigger: string;
  outcome: string;
  knowledgeState: string;
  lifecycleStatus: string;
  validFromRevision: number;
  validToRevision: number | null;
  sourceObservationId: string;
};

export type ArchitectureFlowStep = {
  id: string;
  projectId: string;
  changeId: string;
  flowKey: string;
  stepKey: string;
  sequence: number;
  entityKey: string;
  role: string;
  title: string;
  inputsJson: string;
  action: string;
  outputsJson: string;
  stateReadsJson: string;
  stateWritesJson: string;
  failureModesJson: string;
  nextStepKeysJson: string;
  knowledgeState: string;
  lifecycleStatus: string;
  validFromRevision: number;
  validToRevision: number | null;
  sourceObservationId: string;
};

export type RelationshipEdgeData = Record<string, unknown> & {
  relationship: SemanticRelationship;
  route?: RelationshipRoute;
  emphasis: RelationshipEmphasis;
  zoomLevel: SemanticZoomLevel;
  zoom: number;
  activeFlowName?: string;
  flowSequence?: number;
  flowPayload?: string;
};

export type ArchitectureEdgeData = RelationshipEdgeData;

export type ProjectDetail = {
  project: CatalogProject;
  architecture: {
    entities: ArchitectureEntity[];
    relations: ArchitectureRelation[];
    flows: ArchitectureFlow[];
    flowSteps: ArchitectureFlowStep[];
  };
  facts: Array<{ id: string; kind: string; title: string; statement: string; knowledgeState: string; lifecycleStatus: string }>;
  changes: Array<{ id: string; title: string; summary: string; status: string; progress: number; risk: string; owner: string; baseRevision: number; targetRevision: number | null; updatedAt: string }>;
  evidence: Array<{ id: string; status: string; summary: string; evidenceType: string; sourceRevision: number; changeId: string | null }>;
  events: Array<{ id: string; type: string; summary: string; actor: string; severity: string; projectRevision: number | null; createdAt: string }>;
  revisions: Array<{ id: string; revisionNumber: number; changeId: string | null; summary: string; createdAt: string }>;
};

export type ProjectRegistry = { catalog: CatalogProject[]; detail: ProjectDetail | null };

export type ObjectNodeData = Record<string, unknown> & {
  object: SemanticObject;
  emphasis: ObjectEmphasis;
  zoomLevel: SemanticZoomLevel;
  zoom: number;
  incomingCount: number;
  outgoingCount: number;
  flowSteps: Array<{ sequence: number; role: string; title: string }>;
};

export type RegionNodeData = Record<string, unknown> & {
  region: SemanticRegion;
  emphasis: RegionEmphasis;
  zoomLevel: SemanticZoomLevel;
  zoom: number;
  objectCount: number;
  childRegionCount: number;
  keyObjectNames: string[];
  depth: number;
};

export type ArchitectureNodeData = ObjectNodeData;

