1	import {
2	  SEMANTIC_GRAPH_VERSION,
3	  type SemanticFlow,
4	  type SemanticGraph,
5	  type SemanticObject,
6	  type SemanticObjectType,
7	  type SemanticRegion,
8	  type SemanticRelationship,
9	  type SemanticRelationshipType,
10	  type SemanticState,
11	} from "./semantic-graph";
12	
13	export type CanvasFixtureName = "small" | "medium" | "large" | "complex";
14	
15	const confirmedState: SemanticState = {
16	  value: "confirmed",
17	  label: "Confirmed",
18	  severity: "positive",
19	  source: "knowledge",
20	};
21	
22	const attentionState: SemanticState = {
23	  value: "attention",
24	  label: "Needs evidence",
25	  severity: "attention",
26	  source: "knowledge",
27	};
28	
29	const OBJECT_TYPES: SemanticObjectType[] = ["service", "service", "agent", "storage", "service", "external"];
30	const RELATIONSHIP_TYPES: SemanticRelationshipType[] = ["data", "control", "event", "dependency", "external"];
31	
32	const NAME_PARTS = [
33	  "Ingress", "Identity", "Intent", "Context", "Planner", "Policy", "Execution", "Registry", "Evidence", "Revision",
34	  "Runtime", "Telemetry", "Artifact", "Knowledge", "Delivery", "Coordinator", "Reconciler", "Observation", "Gateway", "Index",
35	];
36	
37	function pad(value: number) {
38	  return String(value).padStart(3, "0");
39	}
40	
41	function makeRegions(name: CanvasFixtureName, count: number, nested: boolean): SemanticRegion[] {
42	  const rootId = `${name}:region:system`;
43	  const regions: SemanticRegion[] = [{
44	    id: rootId,
45	    name: `${name[0].toUpperCase()}${name.slice(1)} System`,
46	    summary: "Fixture system boundary",
47	    importance: { level: "critical", score: 95 },
48	    order: 0,
49	    metadata: { fixture: name, root: true },
50	  }];
51	  for (let index = 1; index < count; index += 1) {
52	    const parentRegionId = nested && index >= count - 2 ? `${name}:region:${pad(((index - 1) % Math.max(1, count - 3)) + 1)}` : rootId;
53	    regions.push({
54	      id: `${name}:region:${pad(index)}`,
55	      name: index % 2 === 0 ? `Domain ${index} · Runtime Plane` : `Domain ${index} · Control Plane`,
56	      summary: index >= count - 2 && nested ? "Nested operational boundary" : "Primary system domain",
57	      parentRegionId,
58	      importance: { level: index < 3 ? "high" : "normal", score: Math.max(38, 82 - index * 5) },
59	      order: index,
60	      metadata: { fixture: name, nested: parentRegionId !== rootId },
61	    });
62	  }
63	  return regions;
64	}
65	
66	function makeObject(name: CanvasFixtureName, index: number, regionIds: string[], longLabels: boolean): SemanticObject {
67	  const objectType = OBJECT_TYPES[index % OBJECT_TYPES.length];
68	  const baseName = `${NAME_PARTS[index % NAME_PARTS.length]} ${objectType === "storage" ? "Store" : objectType === "agent" ? "Agent" : objectType === "external" ? "Provider" : "Service"}`;
69	  const objectName = longLabels && index % 11 === 0
70	    ? `${baseName} for Revision-Pinned Architecture Observation Reconciliation`
71	    : `${baseName} ${pad(index + 1)}`;
72	  return {
73	    id: `${name}:object:${pad(index)}`,
74	    name: objectName,
75	    summary: index % 9 === 0
76	      ? "Coordinates validated system facts across region boundaries while preserving revision identity and human-readable evidence."
77	      : `Owns ${NAME_PARTS[(index + 3) % NAME_PARTS.length].toLowerCase()} responsibilities in the fixture architecture.`,
78	    objectType,
79	    regionId: regionIds[index % regionIds.length],
80	    state: index % 17 === 0 ? attentionState : confirmedState,
81	    importance: index < 2
82	      ? { level: "critical", score: 94 - index }
83	      : index < 8
84	        ? { level: "high", score: 78 - index }
85	        : { level: index % 13 === 0 ? "low" : "normal", score: index % 13 === 0 ? 28 : 52 },
86	    metadata: {
87	      fixture: name,
88	      technology: objectType === "storage" ? "Durable state" : objectType === "agent" ? "Agent runtime" : objectType === "external" ? "External API" : "TypeScript service",
89	      canonicalEntityType: objectType,
90	      repositoryRefs: [`repo://fixture/${name}/${pad(index)}`],
91	    },
92	    layoutHints: { order: index },
93	  };
94	}
95	
96	function portHints(type: SemanticRelationshipType) {
97	  if (type === "event") return { sourcePortRole: "event" as const, targetPortRole: "event" as const, sourcePortSide: "bottom" as const, targetPortSide: "top" as const };
98	  if (type === "dependency") return { sourcePortRole: "downstream" as const, targetPortRole: "upstream" as const, sourcePortSide: "bottom" as const, targetPortSide: "top" as const };
99	  return { sourcePortRole: type === "control" ? "control" as const : "output" as const, targetPortRole: type === "control" ? "control" as const : "input" as const, sourcePortSide: "right" as const, targetPortSide: "left" as const };
100	}
101	
102	function makeRelationships(name: CanvasFixtureName, objectCount: number, relationshipCount: number, isolatedLastObject: boolean) {
103	  const relationships: SemanticRelationship[] = [];
104	  const endpointIds = new Map<string, string>();
105	  const connectedCount = isolatedLastObject ? objectCount - 1 : objectCount;
106	
107	  const add = (sourceIndex: number, targetIndex: number, typeIndex: number) => {
108	    if (sourceIndex === targetIndex || relationships.length >= relationshipCount) return;
109	    const key = `${sourceIndex}:${targetIndex}`;
110	    if (endpointIds.has(key)) return;
111	    const type = RELATIONSHIP_TYPES[typeIndex % RELATIONSHIP_TYPES.length];
112	    const id = `${name}:relationship:${pad(relationships.length)}`;
113	    relationships.push({
114	      id,
115	      sourceObjectId: `${name}:object:${pad(sourceIndex)}`,
116	      targetObjectId: `${name}:object:${pad(targetIndex)}`,
117	      relationshipType: type,
118	      direction: "directed",
119	      label: type === "data" ? "validated payload" : type === "control" ? "invokes" : type === "event" ? "state changed" : type === "dependency" ? "requires" : "external contract",
120	      summary: `Deterministic ${type} relationship from object ${sourceIndex} to object ${targetIndex}.`,
121	      state: relationships.length % 29 === 0 ? attentionState : confirmedState,
122	      importance: { level: relationships.length < 8 ? "high" : "normal", score: relationships.length < 8 ? 72 : 50 },
123	      metadata: { fixture: name, flowIds: [] as string[] },
124	      layoutHints: { ...portHints(type), order: relationships.length },
125	    });
126	    endpointIds.set(key, id);
127	  };
128	
129	  for (let index = 0; index < connectedCount - 1; index += 1) add(index, index + 1, index);
130	  for (let index = 2; index < Math.min(connectedCount, 18); index += 1) add(0, index, index + 1);
131	  for (let index = 3; index < Math.min(connectedCount, 20); index += 1) add(index, 1, index + 2);
132	  for (let offset = 2; relationships.length < relationshipCount && offset < connectedCount; offset += 1) {
133	    for (let source = 0; source < connectedCount && relationships.length < relationshipCount; source += 1) {
134	      const target = (source + offset + (source % 3)) % connectedCount;
135	      add(source, target, source + offset);
136	    }
137	  }
138	  if (relationships.length !== relationshipCount) throw new Error(`Could not build ${name} fixture relationship budget`);
139	  return { relationships, endpointIds };
140	}
141	
142	function makeFlow(
143	  name: CanvasFixtureName,
144	  flowIndex: number,
145	  objectIndexes: number[],
146	  endpointIds: Map<string, string>,
147	): SemanticFlow {
148	  const flowId = `${name}:flow:${flowIndex + 1}`;
149	  const objectIds = objectIndexes.map((index) => `${name}:object:${pad(index)}`);
150	  const relationshipIds = objectIndexes.slice(0, -1)
151	    .map((sourceIndex, index) => endpointIds.get(`${sourceIndex}:${objectIndexes[index + 1]}`))
152	    .filter((id): id is string => Boolean(id));
153	  const steps = objectIndexes.map((objectIndex, index) => ({
154	    id: `${flowId}:step:${index + 1}`,
155	    objectId: `${name}:object:${pad(objectIndex)}`,
156	    sequence: index + 1,
157	    role: index === 0 ? "entry" : index === objectIndexes.length - 1 ? "exit" : index % 3 === 0 ? "guard" : "transformer",
158	    title: index === 0 ? "Accept intent" : index === objectIndexes.length - 1 ? "Publish evidence" : `Transform stage ${index + 1}`,
159	    inputs: index === 0 ? ["user intent"] : [`stage ${index} output`],
160	    action: index % 3 === 0 ? "Validate revision and policy constraints" : "Transform the declared semantic payload",
161	    outputs: index === objectIndexes.length - 1 ? ["verified outcome"] : [`stage ${index + 1} output`],
162	    stateReads: index % 2 === 0 ? ["revision context"] : [],
163	    stateWrites: index % 3 === 0 ? ["evidence trail"] : [],
164	    failureModes: index % 4 === 0 ? ["stale revision", "missing evidence"] : [],
165	    nextStepIds: index < objectIndexes.length - 1 ? [`${flowId}:step:${index + 2}`] : [],
166	    metadata: { fixture: name },
167	  }));
168	  return {
169	    id: flowId,
170	    name: flowIndex === 0 ? "Intent to Verified Change" : flowIndex === 1 ? "Observation to Runtime Context" : "Evidence Reconciliation",
171	    description: "A bounded learning slice over the shared Semantic Graph.",
172	    objectIds,
173	    relationshipIds,
174	    steps,
175	    state: confirmedState,
176	    importance: { level: "high", score: 82 - flowIndex * 3 },
177	    metadata: { fixture: name, trigger: "Declared input", outcome: "Verified system fact" },
178	  };
179	}
180	
181	function buildFixture(
182	  name: CanvasFixtureName,
183	  objectCount: number,
184	  relationshipCount: number,
185	  regionCount: number,
186	  options: { nested?: boolean; longLabels?: boolean; isolated?: boolean; flowCount?: number } = {},
187	): SemanticGraph {
188	  const regions = makeRegions(name, regionCount, Boolean(options.nested));
189	  const leafRegionIds = regions.filter((candidate) => !regions.some((region) => region.parentRegionId === candidate.id)).map((region) => region.id);
190	  const objects = Array.from({ length: objectCount }, (_, index) => makeObject(name, index, leafRegionIds, Boolean(options.longLabels)));
191	  const { relationships, endpointIds } = makeRelationships(name, objectCount, relationshipCount, Boolean(options.isolated));
192	  const flowStarts = [0, Math.min(12, objectCount - 9), Math.min(24, objectCount - 8)];
193	  const flows = Array.from({ length: options.flowCount ?? 2 }, (_, index) => {
194	    const start = Math.max(0, flowStarts[index]);
195	    const length = Math.min(index === 0 ? 8 : 7, objectCount - start - (options.isolated ? 1 : 0));
196	    return makeFlow(name, index, Array.from({ length }, (__, step) => start + step), endpointIds);
197	  });
198	  for (const flow of flows) {
199	    for (const relationshipId of flow.relationshipIds) {
200	      const relationship = relationships.find((candidate) => candidate.id === relationshipId);
201	      const flowIds = relationship?.metadata.flowIds as string[] | undefined;
202	      if (flowIds && !flowIds.includes(flow.id)) flowIds.push(flow.id);
203	    }
204	  }
205	  return {
206	    id: `fixture:${name}`,
207	    version: SEMANTIC_GRAPH_VERSION,
208	    name: `${name[0].toUpperCase()}${name.slice(1)} Canvas Fixture`,
209	    regions,
210	    objects,
211	    relationships,
212	    flows,
213	    scope: {
214	      projectId: `canvas-fixture-${name}`,
215	      revision: 1,
216	      kind: "project",
217	      rootRegionId: regions[0].id,
218	      source: "fixture",
219	    },
220	    metadata: {
221	      fixture: name,
222	      expectedObjectCount: objectCount,
223	      expectedRelationshipCount: relationshipCount,
224	      cases: options,
225	    },
226	  };
227	}
228	
229	export const SMALL_CANVAS_FIXTURE = buildFixture("small", 15, 20, 4, { flowCount: 2 });
230	export const MEDIUM_CANVAS_FIXTURE = buildFixture("medium", 40, 70, 6, { nested: true, flowCount: 3 });
231	export const LARGE_CANVAS_FIXTURE = buildFixture("large", 100, 180, 10, { nested: true, flowCount: 3 });
232	export const COMPLEX_CANVAS_FIXTURE = buildFixture("complex", 64, 124, 9, {
233	  nested: true,
234	  longLabels: true,
235	  isolated: true,
236	  flowCount: 3,
237	});
238	
239	export const CANVAS_FIXTURES: Record<CanvasFixtureName, SemanticGraph> = {
240	  small: SMALL_CANVAS_FIXTURE,
241	  medium: MEDIUM_CANVAS_FIXTURE,
242	  large: LARGE_CANVAS_FIXTURE,
243	  complex: COMPLEX_CANVAS_FIXTURE,
244	};
