import assert from "node:assert/strict";
import { register } from "node:module";
import test from "node:test";

register("./cloudflare-loader.mjs", import.meta.url);

const { LARGE_CANVAS_FIXTURE, SMALL_CANVAS_FIXTURE } = await import("../app/architecture/fixtures.ts");
const { deriveCanvasView, visibleObjectIds } = await import("../app/architecture/interaction.ts");
const { projectSemanticGraph } = await import("../app/architecture/projection.ts");
const { adaptArchitectureToSemanticGraph } = await import("../app/architecture/semantic-adapter.ts");

function tinyImpactGraph() {
  const state = { value: "confirmed", label: "Confirmed", severity: "positive", source: "knowledge" };
  const importance = { level: "normal", score: 50 };
  const graph = {
    id: "tiny",
    version: "canvas-engine-v1",
    name: "Tiny Impact Graph",
    regions: [{ id: "r1", name: "Region One", importance, metadata: {} }],
    objects: ["a", "b", "c", "d", "e"].map((key) => ({
      id: `o-${key}`,
      name: `Object ${key.toUpperCase()}`,
      objectType: "service",
      regionId: "r1",
      state,
      importance,
      metadata: {},
    })),
    relationships: [],
    flows: [],
    scope: { projectId: "tiny", revision: 1, kind: "project", source: "fixture" },
    metadata: {},
  };
  graph.add = (source, target, options = {}) => {
    graph.relationships.push({
      id: options.id ?? `e-${source}-${target}`,
      sourceObjectId: `o-${source}`,
      targetObjectId: `o-${target}`,
      relationshipType: "data",
      direction: options.direction ?? "directed",
      label: "payload",
      state,
      importance,
      metadata: {},
      layoutHints: {},
    });
    return graph;
  };
  return graph;
}

const INSPECT = { mode: "inspect", activeFlowId: null, zoom: 0.7, searchQuery: "" };

test("derives directed upstream and downstream impact with depth when an object is selected", () => {
  const graph = tinyImpactGraph().add("a", "b").add("b", "c").add("c", "d");
  const view = deriveCanvasView(graph, { ...INSPECT, selection: { kind: "object", id: "o-b" } });
  assert.ok(view.impact, "object selection must derive an impact layer");
  assert.equal(view.impact.rootId, "o-b");
  assert.equal(view.impact.upstream.get("o-a"), 1);
  assert.equal(view.impact.downstream.get("o-c"), 1);
  assert.equal(view.impact.downstream.get("o-d"), 2);
  assert.equal(view.impact.objectRoles.get("o-a"), "upstream");
  assert.equal(view.impact.objectRoles.get("o-c"), "downstream");
  assert.equal(view.impact.relationshipRoles.get("e-a-b"), "upstream");
  assert.equal(view.impact.relationshipRoles.get("e-b-c"), "downstream");
  assert.equal(view.impact.relationshipRoles.get("e-c-d"), "downstream");

  assert.equal(view.objectEmphasis.get("o-b"), "primary");
  assert.equal(view.objectEmphasis.get("o-a"), "related");
  assert.equal(view.objectEmphasis.get("o-c"), "related");
  assert.equal(view.objectEmphasis.get("o-d"), "context");
  assert.equal(view.objectEmphasis.get("o-e"), "muted");
  assert.equal(view.relationshipEmphasis.get("e-a-b"), "active");
  assert.equal(view.relationshipEmphasis.get("e-b-c"), "active");
  assert.equal(view.relationshipEmphasis.get("e-c-d"), "related");

  const deep = deriveCanvasView(tinyImpactGraph().add("a", "b").add("b", "c").add("c", "d"), { ...INSPECT, selection: { kind: "object", id: "o-a" } });
  assert.equal(deep.impact.downstream.get("o-b"), 1);
  assert.equal(deep.impact.downstream.get("o-c"), 2);
  assert.equal(deep.impact.downstream.get("o-d"), 3);
});

test("keeps unrelated topology muted and excludes non-impact edges from impact roles", () => {
  const graph = tinyImpactGraph().add("a", "b").add("b", "c").add("a", "c");
  const view = deriveCanvasView(graph, { ...INSPECT, selection: { kind: "object", id: "o-b" } });
  assert.equal(view.objectEmphasis.get("o-e"), "muted", "unrelated topology must recede");
  assert.ok(!view.impact.upstream.has("o-e") && !view.impact.downstream.has("o-e"));
  assert.equal(view.impact.relationshipRoles.get("e-a-c"), undefined, "an edge outside the impact path keeps no role");
  assert.equal(view.relationshipEmphasis.get("e-a-c"), "muted");

  const isolated = deriveCanvasView(tinyImpactGraph(), { ...INSPECT, selection: { kind: "object", id: "o-e" } });
  assert.equal(isolated.impact.rootId, "o-e");
  assert.equal(isolated.impact.upstream.size, 0);
  assert.equal(isolated.impact.downstream.size, 0);
  assert.equal(isolated.objectEmphasis.get("o-e"), "primary");
  assert.equal(isolated.objectEmphasis.get("o-a"), "muted");
});

test("treats bidirectional relationships as two-way impact", () => {
  const graph = tinyImpactGraph().add("a", "b", { direction: "bidirectional" }).add("b", "c");
  const view = deriveCanvasView(graph, { ...INSPECT, selection: { kind: "object", id: "o-a" } });
  assert.equal(view.impact.upstream.get("o-b"), 1);
  assert.equal(view.impact.downstream.get("o-b"), 1);
  assert.equal(view.impact.objectRoles.get("o-b"), "both");
  assert.equal(view.impact.relationshipRoles.get("e-a-b"), "both");
});

