  assert.equal(browse.impact, null, "nothing selected means no impact layer and normal topology");
  assert.ok([...browse.objectEmphasis.values()].every((value) => value === "normal"));

  const relationshipInspect = deriveCanvasView(SMALL_CANVAS_FIXTURE, { ...base, mode: "inspect", selection: { kind: "relationship", id: "small:relationship:000" } });
  assert.equal(relationshipInspect.impact, null);

  const flow = SMALL_CANVAS_FIXTURE.flows[0];
  const trace = deriveCanvasView(SMALL_CANVAS_FIXTURE, { mode: "trace", selection: { kind: "object", id: "small:object:001" }, activeFlowId: flow.id, zoom: 0.9, searchQuery: "" });
