  assert.ok(focus.impact, "Focus selection keeps its impact roles");
  assert.equal(focus.objectEmphasis.get("small:object:001"), "primary");
  assert.equal(focus.objectEmphasis.get("small:object:000"), "related");
  assert.ok([...focus.objectEmphasis.values()].includes("context"), "Focus must retain readable context");
  assert.ok([...focus.objectEmphasis.values()].includes("muted"), "Focus must reduce unrelated topology");
  assert.equal(focus.impact.objectRoles.get("small:object:000"), "upstream");
});

test("keeps the impact closure visible at Landscape zoom", () => {
  const view = deriveCanvasView(LARGE_CANVAS_FIXTURE, {
    mode: "inspect",
    selection: { kind: "object", id: "large:object:000" },
