function adjacentObjectId(sourceObjectId: string, targetObjectId: string, objectId: string) {
  return sourceObjectId === objectId ? targetObjectId : sourceObjectId;
}

function neighbors(graph: SemanticGraph, objectIds: Set<string>) {
  const result = new Set<string>();
  for (const relationship of graph.relationships) {
    if (objectIds.has(relationship.sourceObjectId)) result.add(relationship.targetObjectId);
    if (objectIds.has(relationship.targetObjectId)) result.add(relationship.sourceObjectId);
  }
  return result;
}

function mergeImpactRole(current: ImpactRole | undefined, next: ImpactRole): ImpactRole {
  if (current === undefined || current === next) return next;
  return "both";
}

function walkImpactDirection(
  index: SemanticGraphIndex,
  rootId: string,
  side: "incoming" | "outgoing",
  depths: Map<string, number>,
) {
  const queue: Array<{ id: string; depth: number }> = [{ id: rootId, depth: 0 }];
  while (queue.length > 0) {
    const { id, depth } = queue.shift()!;
    const incident = (side === "incoming" ? index.incomingByObjectId.get(id) : index.outgoingByObjectId.get(id)) ?? [];
    for (const relationship of incident) {
      const nextId = side === "incoming" ? relationship.sourceObjectId : relationship.targetObjectId;
      if (nextId === rootId) continue;
      const nextDepth = depth + 1;
      const knownDepth = depths.get(nextId);
      if (knownDepth !== undefined && knownDepth <= nextDepth) continue;
      depths.set(nextId, nextDepth);
      queue.push({ id: nextId, depth: nextDepth });
    }
  }
}

function deriveImpact(graph: SemanticGraph, index: SemanticGraphIndex, rootId: string): CanvasImpact {
  const upstream = new Map<string, number>();
  const downstream = new Map<string, number>();
  walkImpactDirection(index, rootId, "incoming", upstream);
  walkImpactDirection(index, rootId, "outgoing", downstream);

  const objectRoles = new Map<string, ImpactRole>();
  for (const id of upstream.keys()) objectRoles.set(id, "upstream");
  for (const id of downstream.keys()) objectRoles.set(id, mergeImpactRole(objectRoles.get(id), "downstream"));

  const downstreamSources = new Set<string>([rootId, ...downstream.keys()]);
  const upstreamTargets = new Set<string>([rootId, ...upstream.keys()]);
  const relationshipRoles = new Map<string, ImpactRole>();
  for (const relationship of graph.relationships) {
    const orientations: Array<[string, string]> = relationship.direction === "bidirectional"
      ? [[relationship.sourceObjectId, relationship.targetObjectId], [relationship.targetObjectId, relationship.sourceObjectId]]
      : [[relationship.sourceObjectId, relationship.targetObjectId]];
    let role: ImpactRole | undefined;
    for (const [source, target] of orientations) {
      if (downstreamSources.has(source) && downstream.has(target)) role = mergeImpactRole(role, "downstream");
      if (upstream.has(source) && upstreamTargets.has(target)) role = mergeImpactRole(role, "upstream");
    }
    if (role) relationshipRoles.set(relationship.id, role);
  }

  return { rootId, upstream, downstream, objectRoles, relationshipRoles };
}

