      if (!searchMatches.has(relationship.sourceObjectId) && !searchMatches.has(relationship.targetObjectId)) relationshipEmphasis.set(relationship.id, "muted");
    }
  }

  const impactWanted = interaction.selection?.kind === "object"
    && interaction.selection.id !== null
    && ["inspect", "focus"].includes(interaction.mode)
    && !interaction.activeFlowId;
  const impact = impactWanted
    && index.objectById.has(interaction.selection?.kind === "object" ? interaction.selection.id : "")
    ? deriveImpact(graph, index, (interaction.selection as { kind: "object"; id: string }).id)
    : null;

