export default function Inspector({
  binding,
  mode,
  onClose,
  onFocus,
  onSelect,
}: {
  binding: InspectorBinding | null;
  mode: CanvasMode;
  onClose: () => void;
  onFocus: (objectId: string) => void;
  onSelect: (selection: CanvasSelection) => void;
}) {
  return (
    <aside className={`canvas-inspector ${binding ? "open" : ""}`} aria-hidden={!binding} aria-label="Canvas Inspector">
      {binding && (
        <>
          <header className="inspector-heading">
            <div>
              <small>{TYPE_COPY[binding.typeLabel] ?? binding.typeLabel}</small>
              <strong>{binding.title}</strong>
            </div>
            <button aria-label="Close Inspector" onClick={onClose} type="button">×</button>
          </header>

          <section className="inspector-identity" aria-label="Identity and state">
            <p>{binding.summary}</p>
            <dl>
              <div><dt>State</dt><dd><i className={`severity-${binding.state.severity}`} />{binding.state.label}</dd></div>
              <div><dt>Where</dt><dd>{binding.location}</dd></div>
              <div><dt>Mode</dt><dd>{mode}</dd></div>
            </dl>
            {binding.kind === "object" && (
              <button className="inspector-focus-action" disabled={mode === "focus"} onClick={() => onFocus(binding.object.id)} type="button">
                {mode === "focus" ? "Focused" : "Focus on this object"}<span>F</span>
              </button>
            )}
          </section>

          <details open>
            <summary>Overview</summary>
            {binding.kind === "object" && (
              <dl className="inspector-facts">
                <div><dt>Object</dt><dd>{TYPE_COPY[binding.object.objectType]}</dd></div>
                <div><dt>Importance</dt><dd>{binding.object.importance.level} · {binding.object.importance.score}</dd></div>
                <div><dt>Technology</dt><dd>{String(binding.object.metadata.technology || "Not declared")}</dd></div>
              </dl>
            )}
            {binding.kind === "relationship" && (
              <div className="inspector-endpoints">
                <button onClick={() => binding.source && onSelect({ kind: "object", id: binding.source.id })} type="button"><small>From</small><strong>{binding.source?.name ?? binding.relationship.sourceObjectId}</strong></button>
                <span>→</span>
                <button onClick={() => binding.target && onSelect({ kind: "object", id: binding.target.id })} type="button"><small>To</small><strong>{binding.target?.name ?? binding.relationship.targetObjectId}</strong></button>
              </div>
            )}
            {binding.kind === "flow" && <p>{binding.flow.steps.length} steps across {binding.objects.length} objects and {new Set(binding.objects.map((object) => object.regionId)).size} regions.</p>}
          </details>

          <details open={binding.kind !== "flow"}>
            <summary>Relations</summary>
            {binding.kind === "object" && (
              <>
                <small className="inspector-section-label">Incoming · {binding.incoming.length}</small>
                <RelationshipList direction="in" onSelect={onSelect} relationships={binding.incoming} />
                <small className="inspector-section-label">Outgoing · {binding.outgoing.length}</small>
                <RelationshipList direction="out" onSelect={onSelect} relationships={binding.outgoing} />
              </>
            )}
            {binding.kind === "relationship" && <p>{binding.flows.length > 0 ? `Used by ${binding.flows.map((flow) => flow.name).join(", ")}.` : "Not part of a named Flow."}</p>}
            {binding.kind === "flow" && (
              <div className="inspector-object-list">
                {binding.objects.map((object, index) => <button key={object.id} onClick={() => onSelect({ kind: "object", id: object.id })} type="button"><b>{index + 1}</b><span>{object.name}</span></button>)}
              </div>
            )}
          </details>

          <details open={binding.kind === "flow"}>
            <summary>{binding.kind === "flow" ? "Flow Steps" : "Runtime & Activity"}</summary>
            {binding.kind === "flow" ? (
              <ol className="inspector-flow-steps">
                {binding.flow.steps.map((step) => (
                  <li key={step.id}>
                    <b>{step.sequence}</b>
                    <div><strong>{step.title}</strong><span>{step.action || step.role}</span></div>
                  </li>
                ))}
              </ol>
            ) : <p>Runtime overlay is not attached. Showing declared architecture state.</p>}
          </details>

          {binding.kind === "flow" && (
            <details>
              <summary>Runtime &amp; Activity</summary>
              <p>Runtime overlay is not attached. This trace shows declared semantic order, not live traffic.</p>
            </details>
          )}

          {binding.kind === "object" && binding.flows.length > 0 && (
            <details>
              <summary>Input / Output</summary>
              <div className="inspector-flow-list">
                {binding.flows.map((flow) => <button key={flow.id} onClick={() => onSelect({ kind: "flow", id: flow.id })} type="button"><strong>{flow.name}</strong><span>{flow.steps.length} steps</span></button>)}
              </div>
            </details>
          )}

          <details>
            <summary>Advanced / Raw</summary>
            <pre>{JSON.stringify(binding.raw, null, 2)}</pre>
          </details>
        </>
      )}
    </aside>
  );
}

