() => {
  const nodes = [...document.querySelectorAll("article.object-node")];
  const chips = [...document.querySelectorAll(".object-impact-chip")];
  const edges = [...document.querySelectorAll(".relationship-edge")];
  const strokeOf = (g) => {
    const path = g.querySelector(".react-flow__edge-path");
    return path ? getComputedStyle(path).stroke + " @ " + getComputedStyle(path).strokeWidth : "none";
  };
  return {
    mode: document.querySelector(".canvas-statusbar span")?.textContent,
    emphasisCounts: nodes.reduce((acc, n) => {
      const match = n.className.match(/emphasis-(\w+)/);
      const key = match ? match[1] : "?";
      acc[key] = (acc[key] ?? 0) + 1;
      return acc;
    }, {}),
    chips: chips.map((c) => ({ className: c.className, text: c.textContent.trim(), visible: c.getBoundingClientRect().height > 0 })),
    impactEdges: edges.filter((g) => /impact-/.test(g.className.baseVal)).map((g) => ({ id: g.className.baseVal.match(/impact-\w+/)?.[0], stroke: strokeOf(g) })),
    mutedEdgeSample: edges.filter((g) => /emphasis-muted/.test(g.className.baseVal)).slice(0, 2).map((g) => strokeOf(g)),
    legend: [...document.querySelectorAll(".canvas-reading-key span")].map((s) => s.textContent.trim()),
    inspectorOpen: Boolean(document.querySelector(".canvas-inspector.open")),
    inspectorImpact: document.querySelector(".inspector-impact-summary")?.textContent ?? null,
  };
}

