import { MarkerType, type Edge, type Node } from "@xyflow/react";
import { visibleObjectIds, type CanvasViewModel } from "./interaction";
import type { CanvasLayout } from "./layout";
import { indexSemanticGraph, type SemanticFlowStep, type SemanticGraph } from "./semantic-graph";
import type { ObjectNodeData, RegionNodeData, RelationshipEdgeData } from "./types";

export type CanvasObjectNode = Node<ObjectNodeData, "object">;
export type CanvasRegionNode = Node<RegionNodeData, "region">;
export type CanvasNode = CanvasObjectNode | CanvasRegionNode;
export type CanvasRelationshipEdge = Edge<RelationshipEdgeData, "relationship">;

function handleId(side: "left" | "right" | "top" | "bottom", role: "source" | "target") {
  return `${role}-${side}`;
}

function flowTransition(
  steps: SemanticFlowStep[],
  sourceObjectId: string,
  targetObjectId: string,
) {
  const stepById = new Map(steps.map((step) => [step.id, step]));
  for (const step of steps) {
    if (step.objectId !== sourceObjectId) continue;
    const next = step.nextStepIds.map((id) => stepById.get(id)).find((candidate) => candidate?.objectId === targetObjectId);
    if (!next) continue;
    const payload = step.outputs.length > 0 ? step.outputs.join(" + ") : next.inputs.join(" + ");
    return { sequence: step.sequence, payload, detail: `${step.title} → ${next.title}` };
  }
  return null;
}

export function projectSemanticGraph(
  graph: SemanticGraph,
  layout: CanvasLayout,
  view: CanvasViewModel,
): { nodes: CanvasNode[]; edges: CanvasRelationshipEdge[] } {
  const index = indexSemanticGraph(graph);
  const visibleIds = visibleObjectIds(graph, view);
  const activeFlow = view.activeFlowId ? index.flowById.get(view.activeFlowId) : undefined;
  const regionNodes = graph.regions
    .map<CanvasRegionNode | null>((region) => {
      const rect = layout.regionRects[region.id];
      if (!rect) return null;
      return {
        id: region.id,
        type: "region",
        position: { x: rect.x, y: rect.y },
        data: {
          region,
          emphasis: view.regionEmphasis.get(region.id) ?? "normal",
          zoomLevel: view.zoomLevel,
          zoom: view.zoom,
          objectCount: index.objectsByRegionId.get(region.id)?.length ?? 0,
          childRegionCount: index.childRegionsByRegionId.get(region.id)?.length ?? 0,
          keyObjectNames: (index.objectsByRegionId.get(region.id) ?? [])
            .filter((object) => object.importance.level === "critical" || object.importance.level === "high")
            .sort((left, right) => right.importance.score - left.importance.score || left.name.localeCompare(right.name))
            .slice(0, 3)
            .map((object) => object.name),
          depth: rect.depth,
        },
        draggable: false,
        selectable: false,
        focusable: false,
        zIndex: 0,
        style: { width: rect.width, height: rect.height },
      };
    })
    .filter((node): node is CanvasRegionNode => Boolean(node));

  const objectNodes = graph.objects
    .filter((object) => visibleIds.has(object.id))
    .map<CanvasObjectNode | null>((object) => {
      const rect = layout.objectRects[object.id];
      if (!rect) return null;
      const impactRole = view.impact?.objectRoles.get(object.id);
      const impactDepth = view.impact
        ? Math.min(
          view.impact.upstream.get(object.id) ?? Number.MAX_SAFE_INTEGER,
          view.impact.downstream.get(object.id) ?? Number.MAX_SAFE_INTEGER,
        )
        : Number.MAX_SAFE_INTEGER;
      const isImpactRoot = view.impact?.rootId === object.id;
      return {
        id: object.id,
        type: "object",
        position: { x: rect.x, y: rect.y },
        data: {
          object,
          emphasis: view.objectEmphasis.get(object.id) ?? "normal",
          zoomLevel: view.zoomLevel,
          zoom: view.zoom,
          incomingCount: index.incomingByObjectId.get(object.id)?.length ?? 0,
          outgoingCount: index.outgoingByObjectId.get(object.id)?.length ?? 0,
          flowSteps: (activeFlow?.steps ?? [])
            .filter((step) => step.objectId === object.id)
            .map((step) => ({ sequence: step.sequence, role: step.role, title: step.title })),
          impact: impactRole !== undefined && impactDepth !== Number.MAX_SAFE_INTEGER
            ? { role: impactRole, depth: impactDepth }
            : undefined,
          impactTotals: isImpactRoot && view.impact
            ? {
              upstream: [...view.impact.upstream.values()].filter((depth) => depth === 1).length,
              downstream: [...view.impact.downstream.values()].filter((depth) => depth === 1).length,
            }
            : undefined,
        },
        draggable: true,
        selectable: true,
        selected: view.selection?.kind === "object" && view.selection.id === object.id,
        zIndex: view.objectEmphasis.get(object.id) === "primary" ? 30 : 10,
        style: { width: rect.width, height: rect.height },
      };
    })
    .filter((node): node is CanvasObjectNode => Boolean(node));

  const edges = graph.relationships
    .filter((relationship) => visibleIds.has(relationship.sourceObjectId) && visibleIds.has(relationship.targetObjectId))
    .map<CanvasRelationshipEdge>((relationship) => {
    const route = layout.relationshipRoutes[relationship.id];
    const emphasis = view.relationshipEmphasis.get(relationship.id) ?? "normal";
    const transition = activeFlow ? flowTransition(activeFlow.steps, relationship.sourceObjectId, relationship.targetObjectId) : null;
    const active = emphasis === "active";
    const impactRole = view.impact?.relationshipRoles.get(relationship.id);
    const renderedRoute = route;
    const markerColor = impactRole === "upstream"
      ? "#7fa6c4"
      : impactRole === "downstream"
        ? "#9bd2c1"
        : impactRole === "both"
          ? "#d8f2e8"
          : active
            ? "#e8f4ee"
            : emphasis === "suppressed"
              ? "#243137"
              : emphasis === "muted"
                ? "#4c5d62"
                : relationship.state.severity === "critical"
                  ? "#b98580"
                  : "#83939a";
    return {
      id: relationship.id,
      source: relationship.sourceObjectId,
      target: relationship.targetObjectId,
      sourceHandle: handleId(route?.sourceSide ?? "right", "source"),
      targetHandle: handleId(route?.targetSide ?? "left", "target"),
      type: "relationship",
      data: {
        relationship,
        route: renderedRoute,
        emphasis,
        zoomLevel: view.zoomLevel,
        zoom: view.zoom,
        activeFlowName: activeFlow?.name,
        flowSequence: transition?.sequence,
        flowPayload: transition?.payload,
        impactRole,
      },
      markerEnd: { type: MarkerType.ArrowClosed, width: active ? 18 : 15, height: active ? 18 : 15, color: markerColor },
      selected: view.selection?.kind === "relationship" && view.selection.id === relationship.id,
      selectable: emphasis !== "suppressed",
      focusable: emphasis !== "suppressed",
      zIndex: active ? 24 : emphasis === "related" ? 14 : 1,
    };
    });

  return { nodes: [...regionNodes, ...objectNodes], edges };
}

"use client";

import {
  Background,
  BackgroundVariant,
  Controls,
  MiniMap,
  ReactFlow,
  type EdgeChange,
  type Node,
  type NodeChange,
  type ReactFlowInstance,
  type Viewport,
} from "@xyflow/react";
import { SmartEdgeProvider } from "@tisoap/react-flow-smart-edge";
import type { ReactNode } from "react";
import RelationshipEdge from "./architecture-edge";
import ObjectNode from "./architecture-node";
import RegionNode from "./region-node";
import type { CanvasMode } from "./interaction";
import type { CanvasNode, CanvasObjectNode, CanvasRelationshipEdge } from "./projection";
import type { ObjectNodeData } from "./types";

const nodeTypes = { object: ObjectNode, region: RegionNode };
const edgeTypes = { relationship: RelationshipEdge };

type CanvasKernelProps = {
  nodes: CanvasNode[];
  edges: CanvasRelationshipEdge[];
  mode: CanvasMode;
  onNodesChange: (changes: NodeChange<CanvasNode>[]) => void;
  onEdgesChange: (changes: EdgeChange<CanvasRelationshipEdge>[]) => void;
  onInit: (instance: ReactFlowInstance<CanvasNode, CanvasRelationshipEdge>) => void;
  onNodeClick: (node: CanvasObjectNode) => void;
  onEdgeClick: (edge: CanvasRelationshipEdge) => void;
  onNodeDragStop: (node: CanvasObjectNode) => void;
  onPaneClick: () => void;
  onViewportChange: (viewport: Viewport) => void;
  children?: ReactNode;
};

export default function ArchitectureCanvasKernel({
  nodes,
  edges,
  mode,
  onNodesChange,
  onEdgesChange,
  onInit,
  onNodeClick,
  onEdgeClick,
  onNodeDragStop,
  onPaneClick,
  onViewportChange,
  children,
}: CanvasKernelProps) {
  return (
    <SmartEdgeProvider
      nodes={nodes as Node[]}
      options={{
        preset: "smoothstep",
        routeOnlyWhenBlocked: false,
        routeWhileDragging: true,
        nodePadding: 18,
        gridRatio: 10,
        debounceMs: 16,
      }}
    >
      <ReactFlow<CanvasNode, CanvasRelationshipEdge>
        className={`architecture-canvas-kernel mode-${mode}`}
        edges={edges}
        edgesReconnectable={false}
        edgeTypes={edgeTypes}
        elementsSelectable
        elevateEdgesOnSelect
        maxZoom={1.85}
        minZoom={0.16}
        nodeTypes={nodeTypes}
        nodes={nodes}
        nodesConnectable={false}
        nodesDraggable
        onEdgeClick={(_, edge) => onEdgeClick(edge)}
        onEdgesChange={onEdgesChange}
        onInit={onInit}
        onMoveEnd={(_, viewport) => onViewportChange(viewport)}
        onNodeClick={(_, node) => { if (node.type === "object") onNodeClick(node as CanvasObjectNode); }}
        onNodeDragStop={(_, node) => { if (node.type === "object") onNodeDragStop(node as CanvasObjectNode); }}
        onNodesChange={onNodesChange}
        onPaneClick={onPaneClick}
        onlyRenderVisibleElements
        panOnDrag
        proOptions={{ hideAttribution: true }}
        selectionOnDrag={false}
        zoomOnDoubleClick={false}
      >
        <Background color="rgba(132,151,157,.24)" gap={28} size={1} variant={BackgroundVariant.Dots} />
        <Controls className="architecture-controls" showInteractive={false} />
        <MiniMap
          className="architecture-minimap"
          maskColor="rgba(9,14,17,.68)"
          nodeColor={(node) => {
            if (node.type === "region") return "rgba(118,139,145,.2)";
            const data = node.data as ObjectNodeData | undefined;
            if (data?.impact) return data.impact.role === "upstream" ? "#7fa6c4" : data.impact.role === "downstream" ? "#9bd2c1" : "#d8f2e8";
            return data?.object.state.severity === "critical" ? "#bd7068" : "#688f89";
          }}
          pannable
          zoomable
        />
        {children}
      </ReactFlow>
    </SmartEdgeProvider>
  );
}

