() => {
  const nodes = [...document.querySelectorAll("article.object-node")];
  const chips = [...document.querySelectorAll(".object-impact-chip")];
  const edges = [...document.querySelectorAll(".relationship-edge")];
  const strokeOf = (g) => {
    const path = g.querySelector(".react-flow__edge-path");
    return path ? getComputedStyle(path).stroke + " @ " + getComputedStyle(path).strokeWidth : "none";
  };
  const chipStyle = (c) => {
    const s = getComputedStyle(c);
    return `${s.color} / border ${s.borderTopColor}`;
  };
  return {
    mode: document.querySelector(".canvas-statusbar span")?.textContent,
    emphasisCounts: nodes.reduce((acc, n) => {
      const match = n.className.match(/emphasis-(\w+)/);
      acc[match ? match[1] : "?"] = (acc[match ? match[1] : "?"] ?? 0) + 1;
      return acc;
    }, {}),
    chipCount: chips.length,
    chipSample: chips.slice(0, 3).map((c) => ({ text: c.textContent.trim(), style: chipStyle(c) })),
    impactEdgeStrokes: [...new Set(edges.filter((g) => /impact-/.test(g.className.baseVal)).map((g) => strokeOf(g)))],
    mutedStrokes: [...new Set(edges.filter((g) => /emphasis-muted/.test(g.className.baseVal)).map((g) => strokeOf(g)))],
    edgeLabelGlyphs: [...document.querySelectorAll(".relationship-label b")].map((b) => b.textContent).filter((t) => /▲|▼/.test(t)),
    legend: [...document.querySelectorAll(".canvas-reading-key span")].map((s) => s.textContent.trim()),
    inspectorSummary: document.querySelector(".inspector-impact-summary")?.textContent ?? null,
  };
}

