  const nodes = [...document.querySelectorAll("article.object-node")];
  const chips = [...document.querySelectorAll(".object-impact-chip")];
  const edges = [...document.querySelectorAll(".relationship-edge")];
  const visible = (el) => {
    const r = el.getBoundingClientRect();
    return r.width > 0 && r.bottom >= 0 && r.top <= window.innerHeight;
  };
  return {
    mode: document.querySelector(".canvas-statusbar span")?.textContent,
    renderedNodes: nodes.length,
    emphasisCounts: nodes.reduce((acc, n) => {
      const m = n.className.match(/emphasis-(\w+)/);
      acc[m ? m[1] : "?"] = (acc[m ? m[1] : "?"] ?? 0) + 1;
      return acc;
    }, {}),
    chipsInDom: chips.length,
    chipsVisible: chips.filter(visible).length,
    chipTexts: chips.filter(visible).slice(0, 8).map((c) => c.textContent.trim()),
    rootChip: chips.find((c) => c.classList.contains("role-root"))?.textContent.trim(),
    impactEdges: edges.filter((g) => /impact-/.test(g.className.baseVal)).length,
    mutedEdges: edges.filter((g) => /emphasis-muted/.test(g.className.baseVal)).length,
    renderedEdges: edges.length,
    inspectorSummary: document.querySelector(".inspector-impact-summary")?.textContent ?? null,
  };
}

