    const chipRect = chip.getBoundingClientRect();
    const node = chip.closest("article");
    const label = node?.querySelector(".object-label");
    if (!label) return null;
    const labelRect = label.getBoundingClientRect();
    const intersects = chipRect.bottom > labelRect.top && chipRect.top < labelRect.bottom && chipRect.right > labelRect.left && chipRect.left < labelRect.right;
    return intersects ? { chip: chip.textContent.trim(), chipBottom: Math.round(chipRect.bottom), labelTop: Math.round(labelRect.top) } : null;
  }).filter(Boolean);
  return { checkedChips: chips.length, labelOverlaps: overlap };
}

